document.addEventListener("DOMContentLoaded",()=>{const n=document.querySelectorAll("[data-button-toggle]");n.forEach(n=>{n.addEventListener("click",t=>{const f=t.currentTarget.dataset.buttonToggle,r=document.getElementById(`${f}List`);if(r){const i=n.getAttribute("aria-expanded")==="true";r.classList.toggle("expanded",!i);n.setAttribute("aria-expanded",(!i).toString());const u=n.querySelector("span");u&&(u.textContent=i?"See All":"Show Less")}})})});